os.makedirs('.', exist_ok=True)
for name, content in icons.items():
    with open(f'{name}.svg', 'w', encoding='utf-8') as f:
        f.write(content)
    print(f'  {name}.svg ({len(content)}b)')

print(f'wrote {len(icons)} icons')
